"""Run the post-go order of handoff 5.2 from one list, with a check per row, a log, a lock and a code lock. No stage logic lives here."""
import argparse, csv, glob, hashlib, io, json, os, shutil, subprocess, sys, time
from collections import Counter
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
import common as C  # noqa: E402
import pandas as pd  # noqa: E402

LOG_COLS = ["row", "command", "commit", "start", "end", "seconds", "exit_code", "check", "peak_memory_mb"]
LEDGER_COLS = ["caller", "time", "frozen_hash", "reason"]
READ_KEY = ["caller", "time", "frozen_hash"]
PY = os.environ.get("PY") or str(ROOT / ".venv" / "bin" / "python")
MIN_FREE_GIB = 20


class Stop(Exception):
    """A reason the runner will not go on."""


@dataclass
class Row:
    id: str
    name: str
    steps: list            # [(sub id, argv or None)]
    check: object = None   # fn(sub id) -> "" when it passes, else why not
    read: str = None       # caller name in test_reads.csv, for rows 12 to 14
    long: bool = False
    off: bool = False
    lock: bool = False     # code lock applies from here on


def make(target, *extra):
    return ["make", target, f"PY={PY}", *extra]


def shown(argv):
    """A command as the log and the table print it: no machine paths, because run_log.csv is tracked."""
    return " ".join("$PY" if a == PY else a for a in argv if not a.startswith("PY="))


def src(script, *args):
    return [PY, f"src/{script}", *args]


# ---- checks: "" passes, anything else is the reason -------------------------------
def exists(*names):
    def ck(_):
        gone = [n for n in names if not (C.RES / n).exists()]
        return f"missing {gone}" if gone else ""
    return ck


def models_exist(_sub):
    want = {"6a": ["mlp_seed0.pt", "mlp_seed1.pt", "mlp_seed2.pt"], "6b": ["cnn_seed0.pt"], "6c": ["cnn_seed1.pt"], "6d": ["cnn_seed2.pt"]}[_sub]
    gone = [w for w in want if not (C.MODELS / w).exists()]
    return f"missing {gone}" if gone else ""


def epoch_time(_):
    p = C.RES / "neural" / "epoch_times.csv"
    if not p.exists(): return "no epoch_times.csv"
    d = pd.read_csv(p)
    s = float(d[d.n_train == d.n_train.max()].seconds.iloc[-1])      # row 2's overfit epochs come last and take under a second
    return "" if s < 180 else f"epoch took {s:.0f} s, the 96px fallback applies"


def controls_pass(_):
    bad = []
    for stage in ("baselines", "neural"):
        try: C.control_gate(C.RES / stage / "control.csv")
        except (SystemExit, OSError, ValueError) as e: bad.append(f"{stage}: {e}")
    return "; ".join(bad)


def freeze_parts(_):
    sys.path.insert(0, str(ROOT / "tools"))
    import freeze
    gone = [str(p) for p in freeze.parts() if not p.exists()]
    return f"missing {gone}" if gone else ""


def frozen(_):
    return "" if C.FROZEN.exists() else "no frozen.json"


def manifest(_):
    p = C.RES / "MANIFEST.csv"
    if not p.exists(): return "no MANIFEST.csv"
    d = pd.read_csv(p)
    return "" if d["exists"].astype(str).str.lower().eq("true").all() else "MANIFEST has a row with exists False"


def read_made(caller, *names):
    def ck(_):
        n = len(reads().query("caller == @caller"))
        return exists(*names)(_) or ("" if n else f"no read logged for {caller}")
    return ck


